pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        // The modifier onlyOptimisticAsserter requires msg.sender == address(optimisticAsserter).
        // We are the asserter (address(this) was passed as _optimisticAsserter).
        // No adversarial helper is needed.

        // Call requestPrice; it should always succeed for the correct C, and the mutant also succeeds silently.
        // We record the event with a cheatcode that is allowed.
        vm.recordLogs();
        c.requestPrice(identifier, time, ancillaryData);
        Vm.Log[] memory entries = vm.getRecordedLogs();

        // The general invariant: after a successful call to requestPrice,
        // exactly one PriceRequestAdded event must be emitted with the correct parameters.
        // The mutant breaks this by emitting none.
        bool found = false;
        for (uint i = 0; i < entries.length; i++) {
            if (
                entries[i].topics[0] == keccak256("PriceRequestAdded(bytes32,uint256,bytes)") &&
                entries[i].topics[1] == identifier &&
                entries[i].data == abi.encode(time, ancillaryData)
            ) {
                found = true;
                break;
            }
        }
        assertTrue(found, "PriceRequestAdded event not emitted");
    }
}

