import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract EventCounter {
    uint256 public count;
    function onPriceRequestAdded(bytes32, uint256, bytes memory) external {
        count++;
    }
}

contract InvMutTest is Test {
    C c;
    EventCounter counter;

    function setUp() public {
        c = new C(address(this));
        counter = new EventCounter();
    }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // The requestPrice function requires the caller to be the optimistic asserter (address(this) in setUp).
        // We expect that after a successful call, exactly one PriceRequestAdded event has been emitted.
        // The mutant emits zero, so we install a helper that listens and increments a counter.
        // We then assert that the counter is exactly 1 after the call.
        vm.recordLogs();
        c.requestPrice(identifier, time, ancillaryData);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        uint256 eventCount = 0;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].emitter == address(c)) {
                // topic0 for PriceRequestAdded(bytes32,uint256,bytes)
                if (logs[i].topics[0] == keccak256("PriceRequestAdded(bytes32,uint256,bytes)")) {
                    eventCount++;
                }
            }
        }
        assertTrue(eventCount == 1);
    }
}

