pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    EventCatcher catcher;

    function setUp() public {
        c = new C(address(this));
        catcher = new EventCatcher();
    }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        vm.prank(address(this));
        try c.requestPrice(identifier, time, ancillaryData) {
            uint256 eventsBefore = catcher.count();
            vm.prank(address(this));
            // deploy a temporary forwarder that emits through catcher
            PriceRequester requester = new PriceRequester(c, catcher);
            requester.request(identifier, time, ancillaryData);
            uint256 eventsAfter = catcher.count();
            assertTrue(eventsAfter == eventsBefore + 1);
        } catch {
            assertTrue(false, "requestPrice should not revert");
        }
    }
}

contract EventCatcher {
    uint256 public count;
    event Caught();
    function catchEvent() external {
        count++;
        emit Caught();
    }
}

contract PriceRequester {
    C public immutable c;
    EventCatcher public immutable catcher;
    constructor(C _c, EventCatcher _catcher) {
        c = _c;
        catcher = _catcher;
    }
    function request(bytes32 identifier, uint256 time, bytes calldata ancillaryData) external {
        c.requestPrice(identifier, time, ancillaryData);
        catcher.catchEvent();
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) {
        c = _c;
    }

    function test(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        bool reverted = false;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(address(c.optimisticAsserter()) != address(this) ? reverted : !reverted);
    }
}

